{{
  (() => {
    const cmd = Get_Commande_ById.data?.[0];
    if (!cmd) return "CLIENT : Chargement...";

    const nomComplet = [cmd.Nom, cmd.Prénom].filter(v => v && String(v).trim() !== '' && v !== 'null').join(' ');
    const clientNom = cmd.Societe || nomComplet || "Client inconnu";
    const tel = cmd.Telephone ? `📞 ${cmd.Telephone}` : "📞 Non renseigné";
    const adresse = [cmd.Adresse, cmd.code_postal, cmd.ville].filter(v => v && String(v).trim() !== '' && v !== 'null').join(' ');

    return `CLIENT : ${clientNom} -- ${tel}${adresse ? ' -- ' + adresse : ''}`;
  })()
}}
